args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  { ?father dbp:issue <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> }
  UNION
  { <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> dbo:parent ?father }
  UNION
  { <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> dbp:father ?father }
  UNION
  { <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> dbp:parents ?father }
  UNION
  { <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> dbo:father ?father }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = 'en') }
}

